templates.template:
/* =============================================================================
   Blue Rays — a XenForo 2.3 port of a 2011 phpBB "Orbit"/proSilver board look:
   dark-blue ray header, silver tab bar with a navy active tab, pale-blue page,
   navy category bars, gradient forum rows with boxed stats, blue footer.
   All drawn with CSS (no images) so it stays sharp and needs no uploads.

   Light and dark: every colour below comes from a --br-* variable. The light set is
   on :root; the dark set is applied the same way XenForo 2.3 applies its own
   "alternate" variation — when the member picks Dark, or picks System and their
   device is in dark mode.
   ============================================================================= */

// ---- Colour variables ---------------------------------------------------------

:root
{
	// Tab bar
	--br-nav-bg: linear-gradient(180deg, #ffffff 0%, #f7f7f7 55%, #e4e7ea 100%);
	--br-nav-border: #b7c6d4;
	--br-nav-highlight: rgba(255, 255, 255, .6);
	--br-nav-text: #343434;
	--br-nav-text-shadow: 0 1px 1px #fff;
	--br-nav-arrow: #6f8aa3;
	--br-nav-divider: #d3d9df;
	--br-nav-divider-light: #fff;
	--br-nav-hover-bg: rgba(255, 255, 255, .8);

	// Page and blocks
	--br-body-column: linear-gradient(180deg, #e7f4fa 0%, #f6fbfd 110px, #ffffff 217px);
	--br-body-shadow: 0 0 14px rgba(10, 90, 151, .10);
	--br-subnav-bg: #ffffff;
	--br-border: #b9d5ef;
	--br-link: #0a5a97;
	--br-link-hover: #128dea;
	--br-heading: #0f365a;
	--br-text-dim: #4c5d77;
	--br-stat-label: #116fb8;
	--br-block-footer-bg: #eef4fa;
	--br-minor-header-bg: linear-gradient(180deg, #f5f9fc 0%, #e0ebf6 100%);

	// Category bars
	--br-cat-bg: linear-gradient(180deg, #1c3750 0px, #176198 1px, #19507d 50%, #123f65 100%);
	--br-cat-border: #0d2e4a;

	// Forum / thread rows
	--br-row-bg: linear-gradient(180deg, #ffffff 0%, #fbfcfe 25%, #f5f9fc 50%, #eef4fa 75%, #e0ebf6 100%);
	--br-struct-bg: linear-gradient(180deg, #ffffff 0%, #f5f9fc 60%, #eef4fa 100%);
	--br-stat-bg: #ffffff;
	--br-stat-number: #0e2c3e;
	--br-stat-shadow: 0 1px 1px rgba(10, 90, 151, .08);
	--br-lastpost-bg: rgba(185, 213, 239, .22);
	--br-lastpost-divider: #ffffff;
	--br-user-cell-bg: linear-gradient(180deg, #f1f7fc 0%, #e7f1f9 100%);
}

// Dark values. Header, active tab, category bars' blue and footer stay the same in both.
.m-brDark()
{
	--br-nav-bg: linear-gradient(180deg, #243344 0%, #1b2836 55%, #141e29 100%);
	--br-nav-border: #0b131b;
	--br-nav-highlight: rgba(255, 255, 255, .06);
	--br-nav-text: #d3dde7;
	--br-nav-text-shadow: 0 -1px 0 rgba(0, 0, 0, .6);
	--br-nav-arrow: #6f9cc4;
	--br-nav-divider: #0e1822;
	--br-nav-divider-light: rgba(255, 255, 255, .05);
	--br-nav-hover-bg: rgba(255, 255, 255, .06);

	--br-body-column: linear-gradient(180deg, #0e1824 0%, #122030 110px, #152231 217px);
	--br-body-shadow: 0 0 14px rgba(0, 0, 0, .35);
	--br-subnav-bg: #152231;
	--br-border: #2a4058;
	--br-link: #6bb8f2;
	--br-link-hover: #9fd2ff;
	--br-heading: #cfe3f5;
	--br-text-dim: #a9bdd1;
	--br-stat-label: #6bb8f2;
	--br-block-footer-bg: #122030;
	--br-minor-header-bg: linear-gradient(180deg, #1f3349 0%, #172839 100%);

	--br-cat-bg: linear-gradient(180deg, #06121e 0px, #11406a 1px, #0e3456 50%, #0a2640 100%);
	--br-cat-border: #06121e;

	--br-row-bg: linear-gradient(180deg, #1a2b3d 0%, #172738 50%, #132131 100%);
	--br-struct-bg: linear-gradient(180deg, #192a3c 0%, #152434 60%, #132131 100%);
	--br-stat-bg: #0f1b28;
	--br-stat-number: #e3eef8;
	--br-stat-shadow: none;
	--br-lastpost-bg: rgba(0, 0, 0, .18);
	--br-lastpost-divider: #22364b;
	--br-user-cell-bg: linear-gradient(180deg, #1a2a3c 0%, #16263a 100%);
}

:root[data-variation="alternate"]
{
	.m-brDark();
}

@media (prefers-color-scheme: dark)
{
	:root:not([data-variation])
	{
		.m-brDark();
	}
}

// ---- Header: deep blue gradient with light rays (same in light and dark) ------

.p-header
{
	background-color: #0960a3;
	background-image:
		radial-gradient(ellipse 55% 140% at 50% -10%, rgba(125, 195, 255, .38) 0%, rgba(125, 195, 255, 0) 70%),
		repeating-conic-gradient(from 180deg at 50% -60%, rgba(255, 255, 255, .035) 0deg 2.5deg, rgba(255, 255, 255, 0) 2.5deg 8deg),
		linear-gradient(180deg, #112338 0%, #0f3151 25%, #0d416c 50%, #0b548e 75%, #0960a3 100%);
	color: #fff;
}

.p-header-content
{
	min-height: 110px;
}

// ---- Navigation: silver (dark: steel) tab bar, navy selected tab ----------------

.p-nav
{
	background: var(--br-nav-bg);
	border-top: 1px solid var(--br-nav-highlight);
	border-bottom: 1px solid var(--br-nav-border);
	box-shadow: 0 2px 4px rgba(4, 43, 73, .12);
	color: var(--br-nav-text);
}

.p-nav-list .p-navEl
{
	border-right: 1px solid var(--br-nav-divider);
	box-shadow: 1px 0 0 var(--br-nav-divider-light);
}

.p-nav-list .p-navEl-link
{
	color: var(--br-nav-text);
	font-family: Arial, Helvetica, sans-serif;
	font-weight: 700;
	text-shadow: var(--br-nav-text-shadow);

	&::before
	{
		content: "\203A"; // ›
		display: inline-block;
		margin-right: 7px;
		color: var(--br-nav-arrow);
		font-weight: 700;
	}

	&:hover
	{
		color: var(--br-link);
		text-decoration: none;
	}
}

.p-nav-list .p-navEl:hover
{
	background: var(--br-nav-hover-bg);
}

.p-nav-list .p-navEl.is-selected
{
	background: linear-gradient(180deg, #14507f 0%, #0e3a62 55%, #0d3458 100%);
	border-right-color: #0a2a47;
	box-shadow: inset 0 1px 0 rgba(255, 255, 255, .15);

	.p-navEl-link,
	.p-navEl-splitTrigger
	{
		color: #fff;
		text-shadow: 0 -1px 0 #061420;

		&::before
		{
			color: #9cc8ec;
		}
	}
}

// Log in / Register / account / search on the right of the tab bar
.p-nav .p-navgroup
{
	background: transparent;
}

.p-nav .p-navgroup-link
{
	color: var(--br-nav-text);
	font-family: Arial, Helvetica, sans-serif;
	font-weight: 700;
	text-shadow: var(--br-nav-text-shadow);
	border-left: 1px solid var(--br-nav-divider);
	box-shadow: inset 1px 0 0 var(--br-nav-divider-light);

	&:hover
	{
		background: var(--br-nav-hover-bg);
		color: var(--br-link);
		text-decoration: none;
	}
}

// Sub-navigation under the tabs
.p-sectionLinks
{
	background: var(--br-subnav-bg);
	border-bottom: 1px solid var(--br-border);
	color: var(--br-text-dim);

	a
	{
		color: var(--br-link);
	}
}

// ---- Page: pale blue with a white content column fading in at the top ---------

.p-body-inner
{
	background: var(--br-body-column);
	box-shadow: var(--br-body-shadow);
	padding-top: 12px;
	padding-bottom: 12px;
}

@media (max-width: @xf-responsiveWide)
{
	.p-body-inner
	{
		box-shadow: none;
	}
}

// ---- Blocks ------------------------------------------------------------------

.block-container
{
	border-color: var(--br-border);
	border-radius: 4px;
	overflow: hidden;
}

// Navy category / block title bars
.block-header
{
	background: var(--br-cat-bg);
	border-bottom: 1px solid var(--br-cat-border);
	color: #fff;
	font-family: Arial, Helvetica, sans-serif;
	font-weight: 700;
	text-shadow: 0 -1px 0 #061420;

	a,
	a:hover
	{
		color: #fff;
	}

	.block-desc
	{
		color: rgba(255, 255, 255, .75);
		text-shadow: none;
	}
}

// Light blue minor headers ("Members online", "Forum statistics"…)
.block-minorHeader
{
	background: var(--br-minor-header-bg);
	border-bottom: 1px solid var(--br-border);
	color: var(--br-heading);
	font-family: Arial, Helvetica, sans-serif;
	font-weight: 700;

	a
	{
		color: var(--br-heading);
	}
}

.block-footer
{
	background: var(--br-block-footer-bg);
	border-top-color: var(--br-border);
}

// ---- Forum list rows --------------------------------------------------------

.node + .node
{
	border-top: 1px solid var(--br-border);
}

.node-body
{
	background: var(--br-row-bg);
}

.node-title a
{
	color: var(--br-heading);
	font-family: Arial, Helvetica, sans-serif;
	font-weight: 700;

	&:hover
	{
		color: var(--br-link-hover);
	}
}

.node-description
{
	color: var(--br-text-dim);
}

// Square navy forum icons (brighter blue when there are unread posts)
.node-icon i
{
	display: inline-flex;
	align-items: center;
	justify-content: center;
	width: 40px;
	height: 40px;
	border-radius: 4px;
	background: linear-gradient(180deg, #245f8f 0%, #0d3458 100%);
	box-shadow: inset 0 1px 0 rgba(255, 255, 255, .2), 0 1px 2px rgba(4, 43, 73, .3);
	color: #cfe3f5;
	font-size: 20px;
}

.node--unread .node-icon i
{
	background: linear-gradient(180deg, #2ea3f5 0%, #0a5a97 100%);
	color: #fff;
}

// Topics / Posts shown as boxes with the number on top
.node-stats
{
	> dl.pairs
	{
		display: inline-flex;
		flex-direction: column-reverse;
		align-items: center;
		min-width: 58px;
		margin: 0 2px;
		padding: 4px 6px;
		background: var(--br-stat-bg);
		border: 1px solid var(--br-border);
		border-radius: 4px;
		box-shadow: var(--br-stat-shadow);

		dt
		{
			color: var(--br-stat-label);
			font-size: 11px;
			font-weight: 700;
		}

		dd
		{
			color: var(--br-stat-number);
			font-size: 14px;
			font-weight: 700;
		}
	}
}

// Last post column on a slightly darker tint
.node-extra
{
	background: var(--br-lastpost-bg);
	border-left: 1px solid var(--br-lastpost-divider);
	align-self: stretch;
	padding-left: 10px;
	padding-right: 10px;
}

// ---- Thread list ------------------------------------------------------------

.structItem
{
	background: var(--br-struct-bg);
	border-top-color: var(--br-border);
}

.structItem-title a
{
	color: var(--br-heading);
	font-weight: 700;

	&:hover
	{
		color: var(--br-link-hover);
	}
}

.structItem-cell--meta
{
	color: var(--br-stat-label);
}

// ---- Posts ------------------------------------------------------------------

.message
{
	border-color: var(--br-border);
}

.message-cell--user
{
	background: var(--br-user-cell-bg);
	border-right-color: var(--br-border);
}

.message-name a
{
	font-family: Arial, Helvetica, sans-serif;
}

// ---- Tabs and menu headers: readable text on the pale-blue bars ----------------
// XenForo colours these with the heading text colour, which is white here (it is meant
// for the navy bars). Give them their own matching text and background colours so
// unselected tabs ("Bookmarks", profile tabs, etc.) never end up white on pale blue.

.menu-tabHeader,
.block-tabHeader,
.tabs--standalone
{
	background: var(--br-minor-header-bg);
	border-bottom: 1px solid var(--br-border);
	color: var(--br-text-dim);

	.tabs-tab
	{
		color: var(--br-text-dim);
		text-shadow: none;

		&:hover
		{
			color: var(--br-link-hover);
		}

		&.is-active
		{
			color: var(--br-link);
			border-color: var(--br-link);
		}
	}
}

// Popup menu titles ("Alerts", "Direct messages"...)
.menu-header
{
	background: var(--br-minor-header-bg);
	border-bottom: 1px solid var(--br-border);
	color: var(--br-heading);
	text-shadow: none;

	a
	{
		color: var(--br-heading);
	}
}

// Overlay and mobile-menu title bars: navy with white text, set together
.overlay-title,
.offCanvasMenu-header
{
	background: linear-gradient(180deg, #176198 0%, #19507d 50%, #123f65 100%);
	color: #fff;
	text-shadow: 0 -1px 0 #061420;

	a,
	.overlay-titleCloser,
	.offCanvasMenu-closer
	{
		color: #fff;
	}
}

// ---- Buttons (same in light and dark) --------------------------------------------

.button.button--primary,
a.button.button--primary
{
	background: linear-gradient(180deg, #1b78bd 0%, #0a5a97 100%);
	border: 1px solid #084a7c;
	color: #fff;
	text-shadow: 0 -1px 0 rgba(0, 0, 0, .25);

	&:hover
	{
		background: linear-gradient(180deg, #2a8fd8 0%, #0d68ad 100%);
		color: #fff;
	}
}

// ---- Footer: blue gradient with a soft ray glow (same in light and dark) -------

.p-footer
{
	background-color: #095e9d;
	background-image:
		radial-gradient(ellipse 50% 160% at 50% 0%, rgba(125, 195, 255, .25) 0%, rgba(125, 195, 255, 0) 70%),
		linear-gradient(180deg, #11243a 0%, #0f304f 25%, #0d426d 50%, #0b538a 75%, #095e9d 100%);
	color: #fff;
	text-shadow: 0 1px 1px #000;

	a,
	.p-footer-linkList a
	{
		color: #fff;

		&:hover
		{
			color: #cfe8ff;
			text-decoration: underline;
		}
	}

	.p-footer-copyright
	{
		color: rgba(255, 255, 255, .75);
	}
}
